def gen(rng):
    def ser(vals, L, R, root):
        out = [str(vals[root])]
        q = [root]
        h = 0
        while h < len(q):
            x = q[h]
            h += 1
            for c in (L[x], R[x]):
                if c == -1:
                    out.append('null')
                else:
                    out.append(str(vals[c]))
                    q.append(c)
        while out[-1] == 'null':
            out.pop()
        return ' '.join(out)

    def rand_tree(n):
        L = [-1] * n
        R = [-1] * n
        slots = [(0, 0), (0, 1)]
        for i in range(1, n):
            j = rng.randrange(len(slots))
            slots[j], slots[-1] = slots[-1], slots[j]
            p, s = slots.pop()
            if s == 0:
                L[p] = i
            else:
                R[p] = i
            slots.append((i, 0))
            slots.append((i, 1))
        return L, R

    def chain(n, mode):
        L = [-1] * n
        R = [-1] * n
        for i in range(1, n):
            if mode == 'L':
                s = 0
            elif mode == 'R':
                s = 1
            else:
                s = i % 2
            if s == 0:
                L[i - 1] = i
            else:
                R[i - 1] = i
        return L, R

    def values(n, lo, hi):
        return [rng.randint(lo, hi) for _ in range(n)]

    tests = []
    tests.append('7')
    tests.append('-5 null -6')
    tests.append('1 2 3')
    tests.append('4 2 6 1 3 5 7')
    tests.append('5 3 null 4')
    tests.append('8 null 9 10')
    tests.append('0 0 0 0 0 0 0')
    tests.append('1000000000 -1000000000 1000000000 null -1000000000')
    for n in (2, 3, 4, 5, 7, 9, 12, 16):
        for _ in range(3):
            L, R = rand_tree(n)
            tests.append(ser(values(n, -50, 50), L, R, 0))
    for n in (6, 10, 14):
        for mode in ('L', 'R', 'Z'):
            L, R = chain(n, mode)
            tests.append(ser(values(n, -9, 9), L, R, 0))
    # large cases
    n = 100000
    L, R = rand_tree(n)
    tests.append(ser(values(n, -10**9, 10**9), L, R, 0))
    L = [-1] * n
    R = [-1] * n
    for i in range(n):
        if 2 * i + 1 < n:
            L[i] = 2 * i + 1
        if 2 * i + 2 < n:
            R[i] = 2 * i + 2
    tests.append(ser(values(n, -1000, 1000), L, R, 0))
    for mode in ('L', 'Z'):
        L, R = chain(5000, mode)
        tests.append(ser(values(5000, -10**9, 10**9), L, R, 0))
    # broom: a chain of 4800 nodes ending in a random tree
    m = 95200
    L, R = rand_tree(m)
    L += [-1] * 4800
    R += [-1] * 4800
    for k in range(4800):
        node = m + k
        if k + 1 < 4800:
            L[node] = node + 1
        else:
            L[node] = 0
    tests.append(ser(values(m + 4800, -1000, 1000), L, R, m))
    return tests
